def process_transaction(db_session, payload: dict):
    try:
        record = db_session.insert(payload)
    except KeyError as exc:
        db_session.rollback()
        raise ValueError(f'Invalid payload: {exc}') from exc
    else:
        # Chỉ chạy khi insert thành công không lỗi
        db_session.commit()
        return record
    finally:
        # Luôn chạy để giải phóng connection
        db_session.close()

