# 1. Tự viết Iterator class thủ công
class CountDownIterator:
    def __init__(self, start: int):
        self.current = start
    def __iter__(self):
        return self
    def __next__(self) -> int:
        if self.current <= 0:
            raise StopIteration
        val = self.current
        self.current -= 1
        return val

# 2. Viết bằng Generator tương đương (ngắn gọn, idiomatic)
def countdown_generator(start: int):
    while start > 0:
        yield start
        start -= 1

